    select * into v_r from records where id = (v_rad->>'id')::uuid and deleted_at is null for update;
    if not found then raise notice 'saknas: %', v_rad->>'id'; continue; end if;
    v_ts := ((v_rad->>'datum') || ' 12:00')::timestamp at time zone 'Europe/Stockholm';

    if v_r.data->>'kundtjanst' = v_kt and v_r.data->>'saljare' = v_rad->>'saljare' and v_r.status = 'sald' then
      if nullif(btrim(coalesce(v_r.data->>'kund_telefon', '')), '') is null and v_rad->>'tel' is not null then
        update records set data = data || jsonb_build_object('kund_telefon', v_rad->>'tel') where id = v_r.id;
      end if;
      v_hoppad := v_hoppad + 1; continue;
    end if;

    select exists (select 1 from jsonb_each(v_r.data) e(k, v)
                    where k in ('salt_bredband','salt_mobil','salt_tv','salt_streaming_film','salt_streaming_sport','salt_trygghet')
                      and v not in ('null'::jsonb, 'false'::jsonb, '[]'::jsonb, '""'::jsonb)) into v_har_tj;

    v_data := v_r.data
      || case when v_har_tj then '{}'::jsonb else v_rad->'svc' end
      || jsonb_build_object('saljare', v_rad->>'saljare',
           'sald_datum', case when v_r.status = 'sald' and coalesce(v_r.data->>'sald_datum', '') not in ('', '2026-09-25')
                              then v_r.data->>'sald_datum' else v_rad->>'datum' end,
           'kommentar', concat_ws(E'\n', nullif(btrim(coalesce(v_r.data->>'kommentar', '')), ''), v_rad->>'rad'))
      || case when nullif(btrim(coalesce(v_r.data->>'kund_telefon', '')), '') is null and v_rad->>'tel' is not null
              then jsonb_build_object('kund_telefon', v_rad->>'tel') else '{}'::jsonb end;
    update records set data = v_data where id = v_r.id;

    if v_r.status is distinct from 'sald' then
      update records set status = 'sald' where id = v_r.id;
    end if;

    update records set data = data || jsonb_build_object('kundtjanst', v_kt,
             'kundtjanst_lamnad', coalesce(nullif(data->>'kundtjanst_lamnad', ''), to_char(v_ts at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')))
     where id = v_r.id;

    insert into activities (tenant_id, record_id, activity_type, body, metadata, actor_user_id, actor_kind, occurred_at)
    values (v_r.tenant_id, v_r.id, 'status_change',
            'Såld av kundtjänst, delad med ' || (v_rad->>'namn') || ' (kundtjänstens lista)',
            jsonb_build_object('from', v_r.status, 'to', 'sald', 'kalla', 'kundtjanst_lista_2026-10-19',
                               'kundtjanst', v_kt, 'saljare', v_rad->>'saljare', 'tjanster_behollna', v_har_tj),
            null, 'system', v_ts);
    v_klar := v_klar + 1;
  end loop;
  raise notice 'klara: %, redan inlagda: %', v_klar, v_hoppad;
end $$;
